(() => {
  const STORE = 'coursecairn-progress-v1';
  const LEARNER_STORE = 'coursecairn-learner-v1';
  const DAY_LABELS = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const dayKey = (w,d) => `${w}-${d.toLowerCase()}`;
  const esc = (v='') => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let curriculum, catalog, activeCourseId = 'backend-mastery', state, toastTimer;
  const drafts={};
  let learner = null;
  const main = document.querySelector('#main');
  const route = () => { const [pathname] = location.hash.replace(/^#\/?/,'').replace(/^dsa\/?/,'').split('?'); const [path, ...parts] = pathname.split('/'); return {page:path||'dashboard',parts}; };
  function readState(courseId=activeCourseId){return {progress:{},notes:{},dayLinks:{},bookmarks:[],assessments:{},issues:[],...(drafts[courseId]||Account.read(courseId))}}
  function nextMondayISO(){const d=new Date();d.setHours(0,0,0,0);const offset=(8-d.getDay())%7;if(offset)d.setDate(d.getDate()+offset);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
  async function initializeCourseState(){state=readState();if(!state.courseStartDate){state.courseStartDate=nextMondayISO();await save()}}
  async function save(){const id=activeCourseId,snapshot=JSON.parse(JSON.stringify(state));drafts[id]=snapshot;await Account.save(id,snapshot);if(JSON.stringify(drafts[id])===JSON.stringify(snapshot))delete drafts[id]}
  function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2300)}
  function week(n){return curriculum.weeks.find(w=>w.number===Number(n))}
  function resourcesFor(ids=[]){return ids.map(id=>curriculum.resources.find(r=>r.id===id)||curriculum.videos.find(v=>v.id===id)).filter(Boolean)}
  function modulesForResource(r){return r.kind==='video'?[...new Set(curriculum.weeks.filter(w=>w.videoIds.includes(r.id)).map(w=>w.moduleId))]:(r.modules||[])}
  function progressFor(w,d){return state.progress[dayKey(w,d)]||{}};
  function taskKeys(w){return ['read',...(w.videoIds.length?['watch']:[]),'build','test','explain'];}
  function weekStats(w){let done=0,total=0;for(const d of w.days){const p=progressFor(w.number,d.day);for(const k of taskKeys(w)){total++;if(p[k])done++}}return {done,total,pct:total?Math.round(done/total*100):0}}
  function courseStats(){let done=0,total=0,passed=0;curriculum.weeks.forEach(w=>{const x=weekStats(w);done+=x.done;total+=x.total;if(state.assessments[w.number]?.status==='self_assessed')passed++});return {done,total,pct:total?Math.round(done/total*100):0,passed}}
  function currentLesson(){const start=new Date(`${state.courseStartDate||nextMondayISO()}T00:00:00`),today=new Date();today.setHours(0,0,0,0);const delta=Math.round((Date.UTC(today.getFullYear(),today.getMonth(),today.getDate())-Date.UTC(start.getFullYear(),start.getMonth(),start.getDate()))/86400000);if(delta<0)return {w:curriculum.weeks[0],d:curriculum.weeks[0].days[0],upcoming:true};const weekIndex=Math.floor(delta/7),weekday=delta%7;if(weekIndex>=curriculum.weeks.length)return {w:curriculum.weeks.at(-1),d:curriculum.weeks.at(-1).days.at(-1),courseComplete:true};const w=curriculum.weeks[weekIndex];if(weekday===6)return {w,d:w.days[5],rest:true,next:curriculum.weeks[weekIndex+1]?.days[0]||null};return {w,d:w.days[weekday]};}
  function moduleFor(id){return curriculum.modules.find(m=>m.id===id)}
  function weekLink(w){return `#/${activeCourseId==='dsa'?'dsa/':''}weeks/${w.number}`}
  function dayLink(w,d){return `#/${activeCourseId==='dsa'?'dsa/':''}learn/${w.number}/${d.day.toLowerCase()}`}
  function header(pageTitle){document.querySelector('#sidebar-course').textContent=`${catalog.courses.find(c=>c.id===activeCourseId)?.number||'01'} / ${catalog.courses.find(c=>c.id===activeCourseId)?.title||'Course'}`;document.querySelector('#breadcrumbs').innerHTML=`CourseCairn <span>/</span> ${esc(pageTitle)}`;const {page}=route(),active=page==='learn'||page==='weeks'||page==='phases'||page==='modules'||page==='assessments'?'roadmap':page==='project'?'projects':page;document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===active);if(!['courses','profile'].includes(a.dataset.nav))a.setAttribute('href',`#/${activeCourseId==='dsa'?'dsa/':''}${a.dataset.nav}`)});document.querySelector('#profile-avatar').textContent=(learner.displayName||'Learner').trim().charAt(0).toUpperCase();document.querySelector('#profile-avatar').setAttribute('aria-label',`Learner profile: ${learner.displayName} · ${learner.id}`);const pill=document.querySelector('.guest-pill');if(pill)pill.innerHTML=`<i></i>${esc(learner.displayName)} · ${esc(learner.id)}`;}
  function render(){if(!curriculum||!learner)return;const {page,parts}=route();document.querySelector('#sidebar').classList.remove('open');const pages={home:renderLanding,dashboard:renderDashboard,courses:renderCourses,roadmap:renderRoadmap,resources:()=>parts[0]?renderResource(parts[0]):renderResources(),projects:renderProjects,notes:renderNotes,profile:renderProfile,weeks:()=>renderWeek(parts[0]),learn:()=>renderLesson(parts[0],parts[1]),phases:()=>renderPhase(parts[0]),modules:()=>renderModule(parts[0]),assessments:()=>renderAssessment(parts[0]),project:()=>renderProject(parts[0]),resource:()=>renderResource(parts[0])};(pages[page]||renderDashboard)();if(activeCourseId==='dsa'){renderDsaExtras(page,parts);main.querySelectorAll('a[href^="#/"]').forEach(a=>{if(!/^#\/(courses|profile|dsa)(\/|$)/.test(a.getAttribute('href')))a.setAttribute('href',a.getAttribute('href').replace('#/','#/dsa/'))})}const next=currentLesson(),mobile=document.querySelector('#mobile-continue');mobile.href=dayLink(next.w,next.d);mobile.innerHTML=`<span>Continue · Week ${String(next.w.number).padStart(2,'0')} / ${esc(next.d.day)}</span><b>→</b>`;}
  function renderDsaExtras(page,parts){
    const nav=document.createElement('div');nav.className='button-row';nav.style.marginBottom='18px';nav.innerHTML='<a class="button button-secondary button-small" href="#/roadmap">48-week roadmap</a><a class="button button-secondary button-small" href="#/practice">Problem practice</a><a class="button button-secondary button-small" href="#/interviews">Placement studio</a>';main.prepend(nav);if(page==='resources'){main.querySelectorAll('a[href^="#/resources"]').forEach(a=>a.setAttribute('href',a.getAttribute('href').replace('#/','#/dsa/')))}
    if(page==='home'){renderRoadmap();return renderDsaExtras('roadmap',[])}
    if(page==='practice'||page==='interviews'){header(page==='practice'?'DSA practice':'Placement studio');const attempts=state.dsa?.attempts||[];main.innerHTML=`<div class="page-head"><div><div class="eyebrow">DSA MASTERY · C++17 PRIMARY</div><h1>${page==='practice'?'Practice with evidence.':'Prepare for your next role.'}</h1><p>Independent work, honest reflection, and spaced recall. Results are self-reported.</p></div></div>`;main.append(nav);
      if(page==='interviews'){main.insertAdjacentHTML('beforeend',`<section class="card panel"><h2>Your six-week placement sprint</h2>${curriculum.weeks.slice(42).map(w=>`<div class="read-card"><a href="${weekLink(w)}">Week ${w.number} · ${esc(w.title)}</a><p>${esc(w.checkpoint)}</p></div>`).join('')}<p>Research the exact role, location and eligibility on the official posting. No placement guarantee or universal company exam is implied. OS, DBMS and networks can use an optional 2–4 extra hours per week.</p><a class="button button-secondary" href="#/resources?q=interview">Official preparation sources →</a></section>`);return}
      main.insertAdjacentHTML('beforeend',`<section class="card panel"><label for="practice-week">Practice week</label><select id="practice-week">${curriculum.weeks.map(w=>`<option value="${w.number}">${w.number} · ${esc(w.title)}</option>`).join('')}</select><div id="practice-destinations"></div></section><section class="card panel" style="margin-top:16px"><h2>Record an attempt</h2><p>Try independently before opening an editorial. Include normal, boundary, overflow and adversarial cases; explain time and auxiliary space.</p><form id="dsa-attempt"><label for="attempt-problem">Problem or exercise</label><select id="attempt-problem" name="problemId">${curriculum.problems.map(p=>`<option value="${esc(p.id)}">${esc(p.title)}</option>`).join('')}${curriculum.weeks.map(w=>`<option value="exercise-${w.number}">Week ${w.number} original lab</option>`).join('')}</select><label for="attempt-language">Solution language</label><select id="attempt-language" name="language"><option value="cpp17">C++17 · primary</option><option value="java">Java</option><option value="python3">Python 3</option></select><label for="attempt-result">Result</label><select id="attempt-result" name="result"><option value="attempted">Attempted</option><option value="solved">Solved</option><option value="independent_resolve">Independent correct re-solve</option><option value="needs_revision">Needs revision</option></select><label for="attempt-minutes">Minutes spent (personal measurement)</label><input id="attempt-minutes" name="minutes" type="number" min="1" max="600" required><label><input name="hintUsed" type="checkbox"> Used a hint or editorial</label><label for="attempt-reflection">Approach, complexity, tests and evidence link</label><textarea id="attempt-reflection" name="reflection" maxlength="10000" required></textarea><button class="button button-primary" type="submit">Save attempt →</button></form></section><section class="card panel" style="margin-top:16px"><h2>Recall queue & attempt history</h2><p>${new Set(attempts.map(a=>a.problemId)).size} distinct destinations attempted · ${attempts.filter(a=>a.result==='independent_resolve'&&!a.hintUsed).length} independent re-solves. Task checkboxes do not prove mastery.</p>${attempts.slice().reverse().map(a=>`<div class="read-card"><b>${esc(curriculum.problems.find(p=>p.id===a.problemId)?.title||a.problemId)}</b> · ${esc(a.language)} · ${esc(a.result)} · ${a.minutes} min<p>${esc(a.reflection)}</p><small>Recall: ${a.reviewDates.map(esc).join(' · ')} · ${a.hintUsed?'Hint/editorial used':'No hint reported'}</small></div>`).join('')||'<p>No attempts saved yet.</p>'}</section>`);
      const draw=()=>{const n=Number(document.querySelector('#practice-week').value);document.querySelector('#practice-destinations').innerHTML=`<p>${esc(week(n).artefact)}</p>`+curriculum.problems.filter(p=>p.weeks.includes(n)).map(p=>`<div class="read-card"><a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">${esc(p.title)} ↗</a><small>${esc(p.provider)} · ${esc(p.kind)} · access/payment unknown. If gated, use CSES or the linked sheet.</small></div>`).join('')+'<a href="https://cses.fi/problemset/" target="_blank" rel="noopener noreferrer">CSES practice directory ↗</a>'};draw();document.querySelector('#practice-week').onchange=draw;
      document.querySelector('#dsa-attempt').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget));state.dsa||={language:'cpp17',attempts:[],assessmentHistory:[]};const now=new Date();state.dsa.attempts.push({...values,minutes:Number(values.minutes),hintUsed:values.hintUsed==='on',recordedAt:now.toISOString(),reviewDates:[1,7,21,45].map(days=>new Date(+now+days*86400000).toISOString().slice(0,10))});try{await save();render();toast('Practice attempt saved.')}catch(error){toast(error.message)}};return;
    }
    if(page==='learn'){const w=week(parts[0]),d=w?.days.find(d=>d.day.toLowerCase()===parts[1]);if(!w||!d)return;const section=document.createElement('section');section.className='card lesson-section';section.innerHTML=`<h2>C++ first · language bridge</h2><label for="dsa-language">Learning support</label><select id="dsa-language"><option value="cpp17">C++17 · main track</option><option value="java">Java bridge</option><option value="python3">Python 3 bridge</option></select><p id="dsa-language-help"></p><p><b>Prerequisites:</b> ${w.number===1?'No prior programming required.':`Review Week ${w.number-1} and previous days in this week.`}</p><p><b>Session:</b> ${d.day==='Saturday'?'90 min recall · 150 min independent lab/mock · 60 min review (300 minutes).':'10 min recall · 20 min theory · 20 min targeted chapter/visual · 60 min coding and tests · 10 min reflection.'}</p><p><b>Start here:</b> ${resourcesFor(w.resourceIds).slice(0,1).map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗</a>`).join('')} · Read the section matching today’s objective.</p><p><b>Exercise:</b> ${esc(d.outline)} Write a baseline, justify the invariant, test at least three edge cases, and explain time and auxiliary space. Saturday checkpoint: ${esc(w.checkpoint)}</p><ol><li>Implement today’s task from a blank C++17 file; explain the invariant.</li><li>Create a boundary-case variation and compare its output to a simple baseline.</li><li>Re-solve one relevant practice problem without notes; record hints and complexity.</li></ol><a class="button button-primary button-small" href="#/practice">Open problem practice & recall queue →</a><p class="small-muted">Chapter timestamps were transcribed from publisher descriptions in the supplied research. Live chapter recheck is pending; no frame-by-frame audit is claimed. Choose a chapter relevant to today’s topic.</p>`;main.querySelector('.lesson-main').prepend(section);const select=section.querySelector('select');select.value=state.dsa?.language||'cpp17';const help=()=>{section.querySelector('#dsa-language-help').textContent={cpp17:'Use portable C++17, vector, RAII and const references. Check overflow, iterator lifetime and compiler warnings. unordered_map operations are expected O(1).',java:'Translate one pattern with ArrayList, HashMap, ArrayDeque or PriorityQueue. Account for boxing, comparator contracts and int/long overflow.',python3:'Translate one pattern with list, dict, deque, heapq or bisect. Check recursion depth, object memory and list.pop(0) cost.'}[select.value]};help();select.onchange=async()=>{state.dsa||={language:'cpp17',attempts:[],assessmentHistory:[]};state.dsa.language=select.value;help();try{await save()}catch(error){toast(error.message)}};
    }
  }
  function renderLanding(){header('Field guide');main.innerHTML=`<section class="hero"><div class="hero-copy"><div class="eyebrow">A field guide to backend engineering</div><h1>Go from your first API to production systems.</h1><p>A practical, source-transparent path through Python, FastAPI, PostgreSQL and production engineering. Follow the plan, build real projects, and keep evidence of what you can do.</p><div class="button-row"><a class="button button-primary" href="#/roadmap">Explore curriculum <span>↗</span></a><a class="button button-secondary" href="#/learn/1/monday">Start Week 1 <span>→</span></a></div></div><div class="hero-art"><div class="art-label">THE 36-WEEK ITINERARY</div><div class="phase-list">${curriculum.phases.map(p=>`<div class="phase-row"><span class="phase-no">0${p.id}</span><span>${esc(p.title)}</span><span class="phase-weeks">W${p.range}</span></div>`).join('')}</div><div class="terminal"><span>$ curl localhost:8000/health</span><br><b>→ 200 OK · {"status":"healthy"}</b></div></div></section><div class="stat-grid"><div class="stat-card"><strong>36</strong><span>paced weeks</span></div><div class="stat-card"><strong>24</strong><span>learning modules</span></div><div class="stat-card"><strong>540</strong><span>planned hours</span></div><div class="stat-card"><strong>9</strong><span>portfolio projects</span></div></div><div class="section-heading"><h2>A repeatable learning rhythm</h2><p>Learn it, build it, prove it.</p></div><div class="method-row"><div class="method-step"><span>01</span>Read official docs</div><div class="method-step"><span>02</span>Watch a targeted chapter</div><div class="method-step"><span>03</span>Build from scratch</div><div class="method-step"><span>04</span>Test and explain</div></div><div class="section-heading"><h2>Curated from primary sources</h2></div><div class="source-strip">Python · FastAPI · PostgreSQL · SQLAlchemy · Pydantic · OWASP · Docker · OpenTelemetry · Prometheus <span class="small-muted"> — original publishers and verification limits shown throughout</span></div><div class="section-heading"><h2>Build through nine milestones</h2><a href="#/projects">See the project ladder →</a></div><div class="project-grid">${curriculum.projects.slice(0,3).map(projectCard).join('')}</div><div class="section-heading"><h2>Start with the first study day</h2><a href="#/learn/1/monday">Preview the workbench →</a></div><div class="card panel"><span class="badge badge-terra">WEEK 01 · MONDAY</span><h3 class="section-heading" style="margin:9px 0 2px">${esc(curriculum.weeks[0].days[0].outline)}</h3><p class="small-muted">120 minutes · docs first · hands-on practice · progress saved to your account</p></div>`;}
  function renderCourses(){header('Courses');const active=catalog.courses||[],planned=catalog.plannedCourses||[];main.innerHTML=`<div class="page-head"><div><div class="eyebrow">Your course shelf</div><h1>Choose what you’re learning.</h1><p>Courses stay separate, with their own curriculum and progress. Backend is course 01. Add another course when its content is ready.</p></div></div><div class="course-grid">${active.map(c=>`<article class="card course-card"><div class="course-card-top"><span class="course-number">${esc(c.number||'01')}</span><span class="badge badge-green">Available now</span></div><div class="eyebrow">${esc(c.category||'Course')}</div><h2>${esc(c.title)}</h2><p>${esc(c.description)}</p><div class="course-facts"><span>${esc(c.weeks||'—')} weeks</span><span>${esc(c.modules||'—')} modules</span><span>${esc(c.hours||'—')} hours</span></div><button class="button button-primary" data-action="select-course" data-id="${esc(c.id)}">${c.id===activeCourseId?'Continue this course':'Select this course'} →</button></article>`).join('')}${planned.map(c=>`<article class="card course-card planned-course"><div class="course-card-top"><span class="course-number">${esc(c.number||'')}</span><span class="badge badge-amber">Planned</span></div><div class="eyebrow">${esc(c.category||'Course')}</div><h2>${esc(c.title)}</h2><p>${esc(c.description)}</p><div class="course-facts"><span>Curriculum not added</span></div><button class="button button-secondary" disabled aria-describedby="planned-course-note">Not ready to select</button></article>`).join('')}</div><p id="planned-course-note" class="small-muted" style="margin-top:14px">Planned courses become selectable after their curriculum and source review are added to the course catalog.</p>`;}
  function studyDate(w,offset=0){const date=new Date(`${state.courseStartDate}T00:00:00`);date.setDate(date.getDate()+7*(w.number-1)+offset);return date;}
  function shortDate(date){return new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric'}).format(date);}
  function renderDashboard(){
    const focus=currentLesson(),{w,d}=focus,stats=courseStats(),ws=weekStats(w),course=catalog.courses.find(c=>c.id===activeCourseId),key=dayKey(w.number,d.day);
    const sessionLabel=focus.courseComplete?'YOUR PLAN HAS ENDED':focus.rest?'SUNDAY · ROOM TO RECHARGE':focus.upcoming?'YOUR FIRST SESSION':'TODAY’S SESSION';
    const title=focus.courseComplete?'Time to reflect on your progress.':focus.rest?'A little breathing room.':d.outline;
    const href=focus.courseComplete?'#/roadmap':focus.rest?weekLink(w):dayLink(w,d);
    const action=focus.courseComplete?'Review curriculum':focus.rest?'Catch up on this week':focus.upcoming?'Preview first session':'Start today’s session';
    const noteLabel=focus.rest?'Saturday’s journal':focus.upcoming?'First session journal':focus.courseComplete?'Final session journal':'Today’s journal';
    header('Overview');
    main.innerHTML=`<div class="studio-heading"><div><div class="eyebrow">YOUR LEARNING STUDIO / COURSE ${esc(course.number)}</div><h1>${learner.displayName==='Learner'?'Make room to grow.':`Good to see you, ${esc(learner.displayName)}.`}</h1><p>One focused session brings you a little further.</p></div><div class="date-stamp"><span>${new Intl.DateTimeFormat(undefined,{weekday:'long'}).format(new Date())}</span><b>${shortDate(new Date())}</b></div></div>
      <div class="active-course-bar"><div><span class="course-dot"></span><b>${esc(course.title)}</b><span class="course-subtitle">${curriculum.weeks.length}-week learning path</span></div><a href="#/courses">Switch course ↗</a></div>
      <div class="studio-grid"><div class="studio-main">
        <section class="focus-card"><div class="focus-top"><span class="eyebrow">${sessionLabel}</span><span class="focus-week">WEEK ${String(w.number).padStart(2,'0')}</span></div><h2>${esc(title)}</h2><p>${focus.courseComplete?'Your schedule has ended. Review your saved work and finish any remaining activities.':focus.rest?'Rest, revisit a tricky idea, or finish something from the week. Your next session will be here when you are.':esc(w.focus)}</p><div class="focus-bottom"><a class="button focus-button" href="${href}">${action} <span>↗</span></a><span>${focus.rest||focus.courseComplete?'At your own pace':`${shortDate(studyDate(w,w.days.indexOf(d)))} · ${d.durationMinutes/60} hours planned`}</span></div><svg class="focus-art" viewBox="0 0 220 180" fill="none" aria-hidden="true"><path d="M-20 180C25 70 72 160 110 55S185 10 230-15M-10 210C45 95 82 175 125 80S200 35 250 10M-40 140C5 30 65 125 90 20S165-20 200-45" stroke="currentColor" stroke-width="1.5"/><circle cx="111" cy="55" r="7" fill="currentColor"/></svg></section>
        <section class="card week-panel"><div class="section-top"><div><span class="eyebrow">YOUR WEEK AT A GLANCE</span><h2>${esc(w.title)}</h2></div><a href="${weekLink(w)}" aria-label="Open Week ${w.number}">↗</a></div><div class="calendar-strip">${w.days.map((day,i)=>{const selected=day.day===d.day&&!focus.rest&&!focus.courseComplete;const done=taskKeys(w).every(k=>progressFor(w.number,day.day)[k]);return `<a href="${dayLink(w,day)}" class="calendar-day ${selected?'selected':''} ${done?'completed':''}" ${selected?'aria-current="date"':''}><span>${day.day.slice(0,3)}</span><strong>${studyDate(w,i).getDate()}</strong><small>${done?'✓ Done':day.durationMinutes/60+'h'}</small></a>`}).join('')}<div class="calendar-day rest"><span>Sun</span><strong>${studyDate(w,6).getDate()}</strong><small>Rest</small></div></div><div class="week-caption"><span>${shortDate(studyDate(w))} – ${shortDate(studyDate(w,6))}</span><span>${ws.done}/${ws.total} activities recorded</span></div></section>
        <section class="card journal-panel"><div class="section-top"><div><span class="eyebrow">MAKE IT YOURS</span><h2>${noteLabel}</h2></div><span class="journal-icon">✎</span></div><label for="overview-note">What did you learn, build, or get stuck on?</label><textarea id="overview-note" data-note="${key}" placeholder="A small discovery. A tricky bug. Your next idea…">${esc(state.notes[key]||'')}</textarea><label for="overview-links">Useful links <span>one HTTPS link per line</span></label><textarea id="overview-links" class="link-input" data-day-links="${key}" placeholder="https://github.com/you/todays-work">${esc(state.dayLinks[key]||'')}</textarea><div class="journal-footer"><span>Saved with Week ${w.number} · ${esc(d.day)}</span><button class="button button-primary" data-action="save-note" data-note="${key}">Save journal ↗</button></div></section>
      </div><aside class="studio-rail"><section class="card journey-panel"><div class="eyebrow">YOUR JOURNEY</div><div class="progress-orbit" style="--progress:${stats.pct}%"><div><strong>${stats.pct}<small>%</small></strong><span>course activity</span></div></div><h3>Keep taking the next step.</h3><p>${stats.done} of ${stats.total} learning activities recorded.</p><div class="journey-row"><span>Current week</span><b>${String(w.number).padStart(2,'0')} / ${curriculum.weeks.length}</b></div><div class="journey-row"><span>Self-assessments</span><b>${stats.passed} recorded</b></div><a class="rail-link" href="#/roadmap">Explore your curriculum <span>↗</span></a></section>
      <section class="toolbox"><div class="eyebrow">EVERYTHING FOR THIS COURSE</div><a href="#/resources"><span class="tool-icon">↗</span><span><b>Resource library</b><small>Docs & videos, by module</small></span><i>↗</i></a><a href="#/projects"><span class="tool-icon">▤</span><span><b>Project workshop</b><small>${curriculum.projects.length} builds to put it into practice</small></span><i>↗</i></a><a href="#/notes"><span class="tool-icon">✎</span><span><b>Your notebook</b><small>Reflections & saved sources</small></span><i>↗</i></a></section><div class="schedule-note"><span>⌁</span><p>Your pace, your calendar.<br><a href="#/profile">Adjust your start date →</a></p></div></aside></div>`;
  }
  function renderDayLinks(raw){const hrefs=String(raw||'').split(/\s+/).filter(Boolean).map(value=>{try{const u=new URL(value);return u.protocol==='https:'?u.href:null}catch{return null}}).filter(Boolean);return hrefs.length?`<div class="day-links">${hrefs.map(url=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(new URL(url).hostname)} ↗</a>`).join('')}</div>`:'';}
  function projectForWeek(n){return curriculum.projects.find(p=>p.weeks.split(',').some(part=>{const nums=[...part.matchAll(/\d+/g)].map(m=>+m[0]);return nums.length===1?nums[0]===n:nums.length>1&&n>=nums[0]&&n<=nums[1]}))}
  function renderRoadmap(){header('Curriculum');const current=currentLesson().w;main.innerHTML=`<div class="page-head"><div><div class="eyebrow">THE PATH AHEAD</div><h1>Your curriculum.</h1><p>Open a phase, choose a week, then follow its daily study plan.</p></div><span class="badge badge-green">${curriculum.weeks.length} weeks · ${curriculum.modules.length} modules</span></div><div class="map-intro"><span>01 · Read</span><i>→</i><span>02 · Practice</span><i>→</i><span>03 · Build</span><i>→</i><span>04 · Reflect</span></div><div class="curriculum-map">${curriculum.phases.map(p=>`<details class="phase-branch" ${current.phase===p.id?'open':''}><summary><span class="phase-number">${String(p.id).padStart(2,'0')}</span><span><b>${esc(p.title)}</b><small>Weeks ${esc(p.range)}</small></span><span class="branch-toggle">＋</span></summary><div class="phase-weeks-list">${curriculum.weeks.filter(w=>w.phase===p.id).map(w=>`<a href="${weekLink(w)}" class="map-week ${current.number===w.number?'current':''}"><span class="map-week-no">W${String(w.number).padStart(2,'0')}</span><span><b>${esc(w.title)}</b><small>${esc(moduleFor(w.moduleId)?.title||'')} · 6 sessions · 15 hours</small></span><span class="map-status">${weekStats(w).pct===100?'✓ Recorded':current.number===w.number?'Your week':'↗'}</span></a>`).join('')}</div></details>`).join('')}</div><p class="curriculum-caption">Daily sessions contain study outlines and linked source material. Progress and assessments are self-recorded.</p>`;}
  function renderWeek(n){const w=week(n);if(!w)return renderRoadmap();header(`Week ${w.number}`);const m=moduleFor(w.moduleId),res=resourcesFor([...w.resourceIds,...w.videoIds]),project=projectForWeek(w.number),assessment=state.assessments[w.number];main.innerHTML=`<div class="page-head"><div><div class="eyebrow">Phase ${w.phase} · Module ${String(w.moduleId).padStart(2,'0')}</div><h1>Week ${String(w.number).padStart(2,'0')} — ${esc(w.title)}</h1><p>${esc(w.focus)}</p></div><button class="button button-secondary" data-action="print">Print weekly plan</button></div><div class="detail-columns"><div class="stack"><section class="card panel"><div class="panel-title"><h3>Six study days</h3><span class="badge badge-green">15 hours planned</span></div>${w.days.map((d,i)=>`<a class="task-check" style="text-decoration:none;color:inherit" href="${dayLink(w,d)}"><span class="badge ${taskKeys(w).every(k=>progressFor(w.number,d.day)[k])?'badge-green':'badge'}">${d.durationMinutes/60}h</span><span><b>${d.day}</b><br>${esc(d.outline)}</span><span style="margin-left:auto">→</span></a>`).join('')}<div class="rest-note">Sunday is set aside for rest or catch-up.</div></section><section class="card panel"><div class="panel-title"><h3>This week you build</h3><span class="badge badge-terra">Project checkpoint</span></div><h3>${esc(project?.title||w.artefact||'Weekly artefact')}</h3><p>${esc(project?.criteria||w.checkpoint||'')}</p><div class="muted-banner"><b>Weekly artefact:</b> ${esc(w.artefact||'See the project ladder.')}<br><b>Checkpoint:</b> ${esc(w.checkpoint||'Use the 10-point rubric and preserve evidence.')}</div><a class="button button-secondary button-small" href="#/assessments/${w.number}">Open self-assessment →</a></section></div><div class="stack"><section class="card panel"><div class="eyebrow">Module ${String(w.moduleId).padStart(2,'0')}</div><h3 style="font:20px 'DM Serif Display',serif;margin:7px 0">${esc(m?.title||'')}</h3><p class="small-muted">${esc(m?.coverage||'')}</p><div class="muted-banner">Target: ${esc(m?.passWhen||'')}</div><a class="small-muted" href="#/modules/${m?.slug}">Explore module →</a></section><section class="card panel"><div class="panel-title"><h3>Week sources</h3><button class="icon-button" data-action="bookmark-week" data-week="${w.number}" aria-label="Bookmark week">＋</button></div>${res.map(r=>`<div class="read-card"><a href="#/resources/${r.id}">${esc(r.id)} · ${esc(r.title)}</a><small>${esc(r.author||r.hostname)} · ${esc(r.status||r.role)}</small></div>`).join('')}</section><section class="card panel"><div class="panel-title"><h3>Your assessment</h3><span class="badge">${assessment?esc(assessment.status.replace('_',' ')):'Not submitted'}</span></div><p class="small-muted">Self-assessment status is kept separate from task progress.</p><a class="button button-primary button-small" href="#/assessments/${w.number}">Review the rubric →</a></section></div></div>`;}
  function renderLesson(n,slug){const w=week(n);if(!w)return renderRoadmap();const d=w.days.find(x=>x.day.toLowerCase()===String(slug).toLowerCase())||w.days[0],p=progressFor(w.number,d.day),m=moduleFor(w.moduleId),res=resourcesFor(w.resourceIds),videos=curriculum.videos.filter(v=>w.videoIds.includes(v.id));header(`Week ${w.number} / ${d.day}`);const tasks=[['read','Read the assigned official documentation'],['watch','Watch a selected chapter when one is available'],['build','Build the outlined exercise'],['test','Run checks and capture edge-case evidence'],['explain','Explain the result in your own words']].filter(([key])=>taskKeys(w).includes(key));const timePlan=activeCourseId==='dsa'?(d.day==='Saturday'?[['Recall & review','90 min'],['Independent lab / mock','150 min'],['Tests & postmortem','60 min']]:[['Recall','10 min'],['Theory','20 min'],['Targeted chapter / visual','20 min'],['Code & test','60 min'],['Reflect','10 min']]):d.day==='Saturday'?[['Project plan & acceptance review','30 min'],['Independent build','180 min'],['Testing & debugging','45 min'],['README & checkpoint','45 min']]:[['Orient & recall','10 min'],['Read official sources','25 min'],['Selected chapter or extra reading','25 min'],['Implement / practice','40 min'],['Test, note & recall','20 min']];main.innerHTML=`<div class="page-head"><div><div class="eyebrow"><a href="#/roadmap">Phase ${w.phase}</a> / <a href="${weekLink(w)}">Week ${w.number}</a> / ${esc(d.day)}</div><h1>${esc(d.outline.split(/[.;]/)[0])}</h1><p>${esc(w.title)} · ${esc(m?.title||'')} · ${d.durationMinutes} minutes</p></div><button class="button button-secondary" data-action="bookmark-day" data-week="${w.number}" data-day="${esc(d.day)}">＋ Save day</button></div><div class="lesson-layout"><div class="lesson-main"><div class="outline-alert"><b>Curriculum outline.</b> This day’s source document provides a task outline, not a complete lesson. Work from the linked official docs and record your own evidence. No video watch time is inferred.</div><div class="lesson-objective"><b>Today’s objective</b><br>${esc(d.outline)}<div class="small-muted" style="margin-top:7px">Focus: ${esc(w.focus)}</div></div><section class="card lesson-section"><h2>Read · authoritative sources</h2><div class="read-cards">${res.length?res.map(r=>`<div class="read-card"><a href="#/resources/${r.id}">${esc(r.id)} · ${esc(r.title)}</a><small>${esc(r.hostname)} · ${esc(r.role||'primary')} · mapped to this week</small></div>`).join(''):'<div class="muted-banner">No dedicated written source is mapped to this week. Browse the module references.</div>'}</div></section><section class="card lesson-section"><h2>Watch · publisher-listed chapters</h2>${videos.length?videos.map(v=>`${v.status.includes('LEGACY')?'<div class="video-warning">Legacy supplement — use the current official documentation as your primary guide.</div>':''}<div class="small-muted" style="margin:8px 0"><b>${esc(v.id)} · ${esc(v.title)}</b> by ${esc(v.author)} · <span class="badge ${v.status.includes('LEGACY')?'badge-terra':'badge-green'}">${esc(v.status.split(';')[0])}</span></div>${v.chapters.length?`<div class="small-muted">The curriculum maps this video to a week; it does not assign chapters to each day. Choose a relevant chapter for today’s focus.</div><details class="chapter-disclosure"><summary>Browse ${v.chapters.length} publisher-listed chapters</summary>${v.chapters.map(c=>`<div class="video-chapter"><span>${esc(c.title)} <span class="badge">Publisher-listed</span></span><a class="time" href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">${esc(c.time)} ↗</a><button class="icon-button" data-action="bookmark-chapter" data-video="${v.id}" data-title="${esc(c.title)}" data-start="${c.startSeconds}" aria-label="Bookmark ${esc(c.title)}">＋</button></div>`).join('')}</details>`:`<div class="muted-banner">No chapter timestamps were audited. <a href="${esc(v.url)}" target="_blank" rel="noopener noreferrer">Open original video</a>; no guessed timestamp is provided.</div>`}`).join(''):'<div class="muted-banner">No dedicated approved video chapter is mapped here. Docs-first lesson; video review pending where noted.</div>'}</section><section class="card lesson-section"><h2>Practice · observable output</h2><p>${esc(d.outline)}</p><div class="muted-banner"><b>Expected proof:</b> a working artifact or command output, a check for the stated edge case, and a short explanation. This site does not execute learner code.</div></section><section class="card lesson-section"><h2>Day remark & links</h2><label class="small-muted" for="lesson-note">Your remark: what you built, tested, or want to remember</label><textarea id="lesson-note" data-note="${dayKey(w.number,d.day)}" placeholder="Add a short remark for this study day…">${esc(state.notes[dayKey(w.number,d.day)]||'')}</textarea><label class="small-muted" for="lesson-links" style="display:block;margin-top:10px">Links for this day · one HTTPS URL per line</label><textarea id="lesson-links" data-day-links="${dayKey(w.number,d.day)}" placeholder="https://github.com/you/project\nhttps://example.com/your-notes">${esc(state.dayLinks?.[dayKey(w.number,d.day)]||'')}</textarea><button class="button button-secondary button-small" data-action="save-note" data-note="${dayKey(w.number,d.day)}" style="margin-top:8px">Save remark & links</button></section></div><aside class="lesson-aside"><section class="card panel"><div class="panel-title"><h3>Today’s plan</h3><span class="badge">${d.durationMinutes/60} hours</span></div>${timePlan.map(([label,time])=>`<div class="timebox"><span>${esc(label)}</span><b>${time}</b></div>`).join('')}<hr style="border:0;border-top:1px solid var(--line);margin:10px 0"><div class="small-muted">Suggested session plan. Adjust the time to your task.</div></section><section class="card panel"><div class="panel-title"><h3>Completion evidence</h3><span class="small-muted">${taskKeys(w).filter(k=>p[k]).length}/${tasks.length}</span></div>${tasks.map(([key,label])=>`<label class="task-check"><input type="checkbox" data-task="${key}" data-week="${w.number}" data-day="${esc(d.day)}" ${p[key]?'checked':''}><span>${label}</span></label>`).join('')}<div class="small-muted" style="margin-top:8px">Signals are self-recorded and do not count as a passed weekly assessment. Only steps assigned in the curriculum are counted.</div></section><section class="card panel"><div class="panel-title"><h3>Weekly checkpoint</h3></div><p class="small-muted">${esc(w.checkpoint||'Use the project acceptance criteria and assessment rubric.')}</p><a class="button button-primary button-small" href="#/assessments/${w.number}">Open assessment →</a></section></aside></div>`;}
  function resourceTree(items,query,selectedModule='all'){const buckets=new Map();for(const r of items){const ids=modulesForResource(r).filter(id=>selectedModule==='all'||id===Number(selectedModule));if(!ids.length){if(!buckets.has(0))buckets.set(0,[]);buckets.get(0).push(r);continue}for(const id of ids){if(!buckets.has(id))buckets.set(id,[]);buckets.get(id).push(r)}}return [...buckets.entries()].sort(([a],[b])=>a-b).map(([id,records])=>{const m=moduleFor(id);return `<details class=\"resource-branch\" ${query?'open':''}><summary><span>${id?`M${String(id).padStart(2,'0')} · ${esc(m?.title||'Module')}`:'General references'}</span><b>${records.length} source${records.length===1?'':'s'}</b></summary><div class=\"resource-branch-items\">${records.map(resourceCard).join('')}</div></details>`}).join('')}
  function renderResources(){header('Resource library');const params=new URLSearchParams(location.hash.split('?')[1]||''),q=params.get('q')||'',kind=params.get('type')||'all',status=params.get('status')||'all',module=params.get('module')||'all';const all=[...curriculum.resources,...curriculum.videos].filter(r=>{const text=[r.id,r.title,r.hostname,r.author,r.scope,r.used,r.status].join(' ').toLowerCase();return (!q||text.includes(q.toLowerCase()))&&(kind==='all'||(kind==='video'?r.kind==='video':r.kind!=='video'))&&(status==='all'||(r.kind==='video'&&(status==='legacy'?r.status.includes('LEGACY'):status==='confirmed'?r.status.includes('CONFIRMED'):!r.status.includes('CONFIRMED')&&!r.status.includes('LEGACY'))))&&(module==='all'||modulesForResource(r).includes(Number(module)) )});const matchingWeeks=q?curriculum.weeks.filter(w=>{const mapped=resourcesFor([...w.resourceIds,...w.videoIds]);return [w.title,w.focus,w.artefact,`week ${w.number}`,moduleFor(w.moduleId)?.title,...mapped.map(r=>r.title),...mapped.map(r=>r.id)].join(' ').toLowerCase().includes(q.toLowerCase())&&(module==='all'||w.moduleId===Number(module))}):[];main.innerHTML=`<div class="page-head"><div><div class="eyebrow">Research you can trace</div><h1>Resource library.</h1><p>${curriculum.resources.length} written sources and ${curriculum.videos.length} original videos. Status labels describe the research file’s checks; links are not live monitored.</p></div></div><div class="filter-row"><label class="search-box"><input id="resource-search" type="search" value="${esc(q)}" placeholder="Search title, topic, creator, ID…" aria-label="Search resources"></label><select id="resource-type" aria-label="Filter by type"><option value="all" ${kind==='all'?'selected':''}>All types</option><option value="doc" ${kind==='doc'?'selected':''}>Documentation</option><option value="video" ${kind==='video'?'selected':''}>Video</option></select><select id="resource-module" aria-label="Filter by module"><option value="all" ${module==='all'?'selected':''}>All modules</option>${curriculum.modules.map(m=>`<option value="${m.id}" ${module===String(m.id)?'selected':''}>M${String(m.id).padStart(2,'0')} · ${esc(m.title)}</option>`).join('')}</select><select id="resource-status" aria-label="Filter by research status"><option value="all" ${status==='all'?'selected':''}>All statuses</option><option value="confirmed" ${status==='confirmed'?'selected':''}>Chapter list confirmed</option><option value="legacy" ${status==='legacy'?'selected':''}>Legacy supplement</option><option value="pending" ${status==='pending'?'selected':''}>Review / no chapter audit</option></select></div><div class="small-muted" style="margin-bottom:11px">Showing ${all.length} matching source${all.length===1?'':'s'} · Search is reflected in the URL.</div><div class="resource-tree-note">Open a module branch to browse sources mapped to that part of this course. A source may appear under more than one module.</div><div class="resource-tree">${all.length?resourceTree(all,q,module):`<div class="card empty-state"><h3>No matching sources</h3><p>Try another topic or clear a filter.</p><button class="button button-secondary button-small" data-action="clear-search">Clear search</button></div>`}</div>${matchingWeeks.length?`<div class="section-heading"><h2>Curriculum matches</h2><p>${matchingWeeks.length} week${matchingWeeks.length===1?'':'s'} mapped to this search</p></div><div class="week-grid">${matchingWeeks.map(w=>`<a class="week-card card" href="${weekLink(w)}"><div class="week-card-top">WEEK ${String(w.number).padStart(2,'0')}<span>${esc(moduleFor(w.moduleId)?.title||'')}</span></div><h3>${esc(w.title)}</h3><p>${esc(w.focus)}</p></a>`).join('')}</div>`:''}</div>`;}
  function resourceCurriculumMap(r){const course=catalog.courses.find(c=>c.id===activeCourseId),weeks=curriculum.weeks.filter(w=>w.resourceIds.includes(r.id)||w.videoIds.includes(r.id));return `<div class="curriculum-source-map"><span>${esc(course.title)} / CURRICULUM MAP</span>${weeks.length?`<details><summary>${weeks.length} mapped week${weeks.length===1?'':'s'} · view topics</summary>${weeks.map(w=>`<a class="source-map-week" href="${weekLink(w)}"><b>Week ${String(w.number).padStart(2,'0')} · ${esc(w.title)}</b><small>Module ${String(w.moduleId).padStart(2,'0')} · ${esc(moduleFor(w.moduleId)?.title||'')}<br>Topic: ${esc(w.focus)}</small></a>`).join('')}</details>`:'<small>General reference for this course; no study week is assigned.</small>'}</div>`;}
  function resourceCard(r){const isVideo=r.kind==='video',mods=isVideo?r.used:(r.modules.length?`Modules ${r.modules.join(', ')}`:'Site reference');const weeks=isVideo?r.used:(curriculum.weeks.filter(w=>w.resourceIds.includes(r.id)).map(w=>w.number).join(', ')||'');const status=r.status||r.role;let chapterHtml='';if(isVideo){chapterHtml=r.chapters?.length?`<div class="chapter-list">${r.chapters.map(c=>`<a class="chapter-link" href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">${esc(c.time)} · ${esc(c.title)}</a>`).join('')}</div>`:`<div class="muted-banner" style="margin-top:10px">${r.id==='V07'?'No trustworthy chapter starts captured.':'No chapter list parsed.'} <a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open original</a></div>`;}return `<article class="card resource-card"><div class="resource-id">${esc(r.id)}<br><span class="badge">${isVideo?'VIDEO':'DOC'}</span></div><div><h3><a href="#/resources/${r.id}">${esc(r.title)}</a></h3><p>${esc(isVideo?`By ${r.author} · published ${r.publicationDate}`:r.scope)}</p><div class="domain">${esc(isVideo?'youtube.com':r.hostname)} · ${esc(mods)} ${weeks?`· ${esc(weeks)}`:''}</div><div style="margin-top:6px"><span class="badge ${String(status).includes('LEGACY')?'badge-terra':String(status).includes('CONFIRMED')||status==='primary'?'badge-green':'badge'}">${esc(String(status).replace(/\.$/,''))}</span>${r.notes?` <span class="small-muted">${esc(r.notes.replace(/\*\*/g,''))}</span>`:''}</div>${resourceCurriculumMap(r)}${chapterHtml}</div><div class="resource-actions"><button class="icon-button" data-action="bookmark-resource" data-id="${r.id}" aria-label="Bookmark ${esc(r.title)}">＋</button><a class="button button-secondary button-small" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open ↗</a></div></article>`;}
  function renderResource(id){const r=curriculum.resources.find(x=>x.id===id)||curriculum.videos.find(x=>x.id===id);if(!r)return renderResources();header(`Source ${r.id}`);const usedWeeks=curriculum.weeks.filter(w=>w.resourceIds.includes(r.id)||w.videoIds.includes(r.id));main.innerHTML=`<div class="page-head"><div><div class="eyebrow">${esc(r.id)} · ${r.kind==='video'?'Original video':'Written reference'}</div><h1>${esc(r.title)}</h1><p>${esc(r.kind==='video'?`By ${r.author} · ${r.publicationDate}`:`${r.hostname} · ${r.role}`)}</p></div><button class="button button-secondary" data-action="bookmark-resource" data-id="${r.id}">＋ Bookmark source</button></div><div class="detail-columns"><section class="card panel"><div class="panel-title"><h3>Source and research status</h3><span class="badge ${String(r.status).includes('LEGACY')?'badge-terra':'badge-green'}">${esc(String(r.status).replace(/\.$/,''))}</span></div><p>${esc(r.scope||r.used||r.notes||'Source mapped in the curriculum.')}</p>${r.notes?`<div class="video-warning">${esc(r.notes.replace(/\*\*/g,''))}</div>`:''}<div class="button-row"><a class="button button-primary button-small" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Visit original source ↗</a><button class="button button-secondary button-small" data-action="report-issue" data-id="${r.id}">Report a broken link</button></div>${r.chapters?.length?`<div class="section-heading"><h2>Publisher-listed chapters</h2></div>${r.chapters.map(c=>`<div class="video-chapter"><span>${esc(c.title)} · <span class="badge">Publisher-listed</span></span><a class="time" target="_blank" rel="noopener noreferrer" href="${esc(c.url)}">${esc(c.time)} ↗</a><button class="icon-button" data-action="bookmark-chapter" data-video="${r.id}" data-title="${esc(c.title)}" data-start="${c.startSeconds}" aria-label="Bookmark ${esc(c.title)}">＋</button></div>`).join('')}`:''}</section><section class="card panel"><h3 style="font:20px 'DM Serif Display',serif">Curriculum topics</h3><div class="source-course-label">${esc(catalog.courses.find(c=>c.id===activeCourseId)?.title||'')}</div>${usedWeeks.length?usedWeeks.map(w=>`<div class="task-check"><a href="${weekLink(w)}">Week ${String(w.number).padStart(2,'0')} · ${esc(w.title)} ↗</a><small style="display:block">Module ${w.moduleId} · ${esc(moduleFor(w.moduleId)?.title||'')}<br>Topic: ${esc(w.focus)}</small></div>`).join(''):'<p class="small-muted">This source is part of the site reference set.</p>'}<div class="muted-banner">Last-reviewed details are not supplied for every source. Research status comes from the companion curriculum and does not imply a fresh launch audit.</div></section></div>`;}
  function renderProjects(){header('Project ladder');main.innerHTML=`<div class="page-head"><div><div class="eyebrow">${activeCourseId==='dsa'?'Eight independent phase gates':'Nine portfolio milestones'}</div><h1>Build the proof.</h1><p>Each milestone grows from the week-by-week curriculum. Record your evidence, assess it yourself, and keep the distinction between self-assessment and trusted verification clear.</p></div></div><div class="project-grid">${curriculum.projects.map((p,i)=>`<article class="card project-card"><div class="week-card-top"><span>${esc(p.id)} · STAGE ${String(i+1).padStart(2,'0')}</span><span class="badge">Weeks ${esc(p.weeks)}</span></div><h3>${esc(p.title)}</h3><p>${esc(p.criteria)}</p><a class="button button-secondary button-small" href="#/project/${p.id}">Open milestone →</a></article>`).join('')}</div>`;}
  function renderProject(id){const p=curriculum.projects.find(x=>x.id===id);if(!p)return renderProjects();header(p.title);const nums=[...p.weeks.matchAll(/\d+/g)].map(x=>+x[0]);const related=curriculum.weeks.filter(w=>nums.length===1?w.number===nums[0]:nums.length>1&&w.number>=nums[0]&&w.number<=nums[1]);main.innerHTML=`<div class="page-head"><div><div class="eyebrow">${esc(p.id)} · Weeks ${esc(p.weeks)}</div><h1>${esc(p.title)}</h1><p>${esc(p.criteria)}</p></div><button class="button button-secondary" data-action="bookmark-project" data-id="${p.id}">＋ Save project</button></div><div class="detail-columns"><section class="card panel"><h2 style="font:23px 'DM Serif Display',serif">Acceptance evidence</h2><div class="muted-banner">Project requirements from the curriculum: <b>${esc(p.criteria)}</b></div><h3 class="section-heading" style="font-size:17px">Repository checklist</h3><div class="task-check">${activeCourseId==='dsa'?'C++17 implementation, build commands, invariant and complexity explanation':'README with setup, API contract, tests and architecture note'}</div><div class="task-check">.env.example with placeholders and no real secrets</div><div class="task-check">${activeCourseId==='dsa'?'Normal, adversarial and boundary tests; independent fresh exercise':'Sample requests, test instructions and change log'}</div><label class="small-muted" for="project-repo">GitHub repository URL (optional)</label><input class="text-input" id="project-repo" data-project-repo="${p.id}" type="url" inputmode="url" placeholder="https://github.com/you/project" value="${esc(state.notes[`project-url-${p.id}`]||'')}"><label class="small-muted" for="project-evidence" style="display:block;margin-top:10px">Evidence: test output, demo, README or reviewer notes</label><textarea id="project-evidence" data-project-note="${p.id}" placeholder="Paste a repository URL, test output, or short explanation…">${esc(state.notes[`project-${p.id}`]||'')}</textarea><button class="button button-secondary button-small" data-action="save-project-note" data-id="${p.id}" style="margin-top:8px">Save evidence</button></section><section class="card panel"><h3 style="font:20px 'DM Serif Display',serif">Related weeks</h3>${related.length?related.map(w=>`<div class="task-check"><a href="${weekLink(w)}">Week ${w.number} · ${esc(w.title)} ↗</a></div>`).join(''):'<p class="small-muted">See the listed milestone weeks in the roadmap.</p>'}<a class="button button-primary button-small" href="#/assessments/${related[related.length-1]?.number||1}">Open related assessment →</a><div class="muted-banner" style="margin-top:12px">A project status is self-assessed unless a trusted reviewer or test runner evaluates it.</div></section></div>`;}
  function renderAssessment(n){const w=week(n);if(!w)return renderRoadmap();header(`Week ${w.number} assessment`);const a=state.assessments[w.number]||{checks:[],score:0,evidence:''},criteria=activeCourseId==='dsa'?['Problem modeling','Algorithm choice','Correctness','Complexity','Communication/testing']:['Understanding','Implementation','Debugging','Testing','Documentation'];const passed=a.status==='self_assessed';main.innerHTML=`<div class="page-head"><div><div class="eyebrow">Week ${String(w.number).padStart(2,'0')} checkpoint</div><h1>Assess the work.</h1><p>${esc(w.title)} · ${esc(w.artefact||'Weekly artefact')}</p></div><span class="badge ${passed?'badge-green':'badge'}">${passed?'Self-assessed':'Not submitted'}</span></div><div class="muted-banner">This is a learner self-assessment, not an automatic code grade or trusted review. A pass requires at least 8/10 and every critical check. If a security defect exists, record needs revision even if the score is high.</div><div class="detail-columns" style="margin-top:15px"><section class="card panel"><h2 style="font:23px 'DM Serif Display',serif">Rubric · 0–2 each</h2><p class="small-muted">0 — cannot explain / implement · 1 — partial or with prompts · 2 — independently working and explained.</p>${criteria.map((c,i)=>`<label class="task-check"><span style="min-width:110px"><b>${c}</b></span><select data-score="${i}" aria-label="${c} score" style="margin-left:auto;border:1px solid var(--line);border-radius:6px;padding:5px;background:var(--paper)"><option value="0" ${Number(a.scores?.[i]||0)===0?'selected':''}>0</option><option value="1" ${Number(a.scores?.[i]||0)===1?'selected':''}>1</option><option value="2" ${Number(a.scores?.[i]||0)===2?'selected':''}>2</option></select></label>`).join('')}<label class="task-check"><input type="checkbox" data-critical ${a.critical?`checked`:''}><span>All critical checks passed (including security and data integrity where relevant).</span></label><label class="small-muted" for="assessment-evidence">Evidence: test output, demo, README or reviewer notes</label><textarea id="assessment-evidence" placeholder="Describe what you submitted and the evidence you checked…">${esc(a.evidence||'')}</textarea><div class="panel-title" style="margin-top:12px"><span>Score <b id="score-display">${(a.scores||[0,0,0,0,0]).reduce((x,y)=>x+Number(y),0)}/10</b></span><button class="button button-primary button-small" data-action="submit-assessment" data-week="${w.number}">Record self-assessment</button></div><button class="button button-secondary button-small" data-action="needs-revision" data-week="${w.number}">Needs revision</button><p class="small-muted">Recording a result does not mark the study tasks as complete.</p></section><section class="stack"><section class="card panel"><div class="eyebrow">Project checkpoint</div><h3 style="font:19px 'DM Serif Display',serif">${esc(w.artefact||'Weekly build')}</h3><p>${esc(w.checkpoint||'Use the rubric and preserve evidence.')}</p></section><section class="card panel"><h3 style="font:19px 'DM Serif Display',serif">Weekly plan completion</h3><div class="progress-track"><div class="progress-fill" style="width:${weekStats(w).pct}%"></div></div><div class="progress-meta"><span>Tasks recorded</span><span>${weekStats(w).pct}%</span></div><a href="${weekLink(w)}">Return to Week ${w.number} →</a></section></section></div>`;}
  function renderModule(slug){const m=curriculum.modules.find(x=>x.slug===slug)||curriculum.modules[Number(slug)-1];if(!m)return renderRoadmap();header(m.title);const weeks=curriculum.weeks.filter(w=>w.moduleId===m.id),res=resourcesFor(m.resourceIds);main.innerHTML=`<div class="page-head"><div><div class="eyebrow">Module ${String(m.id).padStart(2,'0')} · Weeks ${esc(m.weeks)}</div><h1>${esc(m.title)}</h1><p>${esc(m.coverage)}</p></div></div><div class="detail-columns"><section class="card panel"><h2 style="font:23px 'DM Serif Display',serif">Build & pass criteria</h2><p><b>Build:</b> ${esc(m.build)}</p><p><b>Pass when:</b> ${esc(m.passWhen)}</p><h3 style="font:18px 'DM Serif Display',serif">Mapped weeks</h3>${weeks.map(w=>`<div class="task-check"><a href="${weekLink(w)}">Week ${w.number} · ${esc(w.title)} ↗</a></div>`).join('')}</section><section class="card panel"><h3 style="font:20px 'DM Serif Display',serif">Read first</h3>${res.map(r=>`<div class="read-card"><a href="#/resources/${r.id}">${esc(r.id)} · ${esc(r.title)}</a><small>${esc(r.hostname)}</small></div>`).join('')}<h3 style="font:18px 'DM Serif Display',serif;margin-top:16px">Targeted videos</h3>${m.videoIds.map(id=>{const v=curriculum.videos.find(x=>x.id===id);return v?`<div class="read-card"><a href="#/resources/${id}">${id} · ${esc(v.title)}</a><small>${esc(v.status)}</small></div>`:''}).join('')||'<div class="muted-banner">No dedicated approved video; use the official references.</div>'}</section></div>`;}
  function renderPhase(id){const p=curriculum.phases.find(x=>x.id===Number(id));if(!p)return renderRoadmap();header(p.title);const ws=curriculum.weeks.filter(w=>w.phase===p.id);main.innerHTML=`<div class="page-head"><div><div class="eyebrow">Phase ${p.id} · Weeks ${p.range}</div><h1>${esc(p.title)}</h1><p>A six-week section of the ${curriculum.plannedWeeks}-week learning path.</p></div></div><div class="week-grid">${ws.map(w=>`<a class="week-card card" href="${weekLink(w)}"><div class="week-card-top">WEEK ${String(w.number).padStart(2,'0')}<span>15h</span></div><h3>${esc(w.title)}</h3><p>${esc(moduleFor(w.moduleId)?.title||'')}</p></a>`).join('')}</div>`;}
  function profileCourseStats(data,saved){let done=0,total=0,sessions=0,passed=0;for(const w of data.weeks){const keys=taskKeys(w);for(const d of w.days){const p=saved.progress[dayKey(w.number,d.day)]||{};total+=keys.length;done+=keys.filter(k=>p[k]).length;if(keys.every(k=>p[k]))sessions++}if(saved.assessments[w.number]?.status==='self_assessed')passed++}return {done,total,sessions,passed,pct:total?Math.round(done/total*100):0,days:data.weeks.reduce((n,w)=>n+w.days.length,0)}}
  function profileCourseCard(course,data,saved){const x=profileCourseStats(data,saved),active=course.id===activeCourseId;return `<article class="card profile-progress-card ${active?'current-course':''}"><div class="profile-progress-top"><span class="eyebrow">COURSE ${esc(course.number||'')}</span><span class="badge ${active?'badge-green':''}">${active?'Current course':x.done?'In progress':'Not started'}</span></div><h3>${esc(course.title)}</h3><div class="profile-progress-value"><strong>${x.pct}<small>%</small></strong><span>activity recorded</span></div><div class="progress-track"><div class="progress-fill" style="width:${x.pct}%"></div></div><div class="profile-progress-details"><span><b>${x.sessions} / ${x.days}</b> sessions completed</span><span><b>${x.passed}</b> weekly self-assessments</span><span><b>${x.done} / ${x.total}</b> activities recorded</span></div><button class="button ${active?'button-primary':'button-secondary'} button-small" data-action="select-course" data-id="${esc(course.id)}">${active?'Continue course':'Open course'} ↗</button></article>`;}
  async function loadProfileCourseProgress(){const container=document.querySelector('#profile-course-progress');if(!container)return;const courses=[...catalog.courses].sort((a,b)=>Number(b.id===activeCourseId)-Number(a.id===activeCourseId));container.innerHTML=courses.map(c=>`<div class="card profile-progress-card" data-progress-course="${esc(c.id)}"><h3>${esc(c.title)}</h3><p class="small-muted">Loading course progress…</p></div>`).join('');await Promise.all(courses.map(async c=>{const slot=[...container.children].find(el=>el.dataset.progressCourse===c.id);try{let data;if(c.id===activeCourseId)data=curriculum;else{const response=await fetch(`content/${c.curriculum}`);if(!response.ok)throw new Error('Course could not load');data=await response.json()}if(container.isConnected&&slot?.isConnected)slot.outerHTML=profileCourseCard(c,data,c.id===activeCourseId?state:readState(c.id));}catch{if(slot?.isConnected)slot.innerHTML=`<h3>${esc(c.title)}</h3><p class="small-muted">Progress could not load. Your saved data remains in your account.</p><button class="button button-secondary button-small" data-action="retry-profile-progress">Try again</button>`;}}));}
  function renderProfile(){
    const course=catalog.courses.find(c=>c.id===activeCourseId)||catalog.courses[0];
    header('Learner profile');
    main.innerHTML=`<div class="page-head"><div><div class="eyebrow">Your identity & schedule</div><h1>Learner profile.</h1><p>Your unique profile connects your courses, progress and notes across devices.</p></div><span class="badge">Signed in · @${esc(learner.username)}</span></div>
      <section class="profile-courses-section" aria-labelledby="profile-courses-title"><div class="section-top"><div><div class="eyebrow">YOUR LEARNING, IN ONE PLACE</div><h2 id="profile-courses-title">My course progress</h2></div><a class="button button-secondary button-small" href="#/courses">Browse courses ↗</a></div><div class="profile-course-progress" id="profile-course-progress" aria-live="polite"></div><p class="small-muted">Each course has its own saved progress. Planned courses appear here when their curriculum becomes available.</p></section><div class="profile-layout"><section class="card panel profile-card"><div class="profile-emblem">${esc((learner.displayName||'L').trim().charAt(0).toUpperCase())}</div><label for="learner-name">Display name</label><input class="text-input" id="learner-name" maxlength="48" value="${esc(learner.displayName||'Learner')}" autocomplete="nickname"><div class="profile-id"><span class="eyebrow">YOUR UNIQUE LEARNER ID</span><strong>${esc(learner.id)}</strong><small>Created ${new Date(learner.createdAt).toLocaleDateString()}</small></div><button class="button button-primary" data-action="save-profile">Save profile</button></section>
      <section class="card panel"><div class="eyebrow">ACTIVE COURSE</div><h2 class="profile-course-title">${esc(course.title)}</h2><p class="small-muted">Course ${esc(course.number||'01')} · This schedule applies only to this course.</p><label for="course-start-date">Planned start date <span class="small-muted">(choose a Monday)</span></label><input class="text-input" id="course-start-date" type="date" value="${esc(state.courseStartDate||'')}"><div class="muted-banner" style="margin-top:12px">Your weekday topic and week number follow this date. Sunday stays a rest or catch-up day. Changing the date keeps your saved notes and progress.</div><button class="button button-secondary button-small" data-action="save-course-start" style="margin-top:12px">Save course schedule</button></section></div>
      <section class="card panel profile-storage"><div class="panel-title"><h3>Account & data</h3><span class="badge badge-amber">Private account</span></div><p>Your profile and course data are saved in your account. Export includes all courses, notes, links, bookmarks, progress and assessments.</p><div class="button-row"><button class="button button-secondary button-small" data-action="export">Export all my data ↧</button><button class="button button-secondary button-small" data-action="logout">Sign out</button><button class="button button-secondary button-small" data-action="retry-save">Retry pending save</button><a class="button button-secondary button-small" href="#/courses">Manage courses →</a></div></section>`;
    loadProfileCourseProgress();
  }
  function renderNotes(){header('Notes & bookmarks');const notes=Object.entries(state.notes).filter(([,v])=>v.trim());main.innerHTML=`<div class="page-head"><div><div class="eyebrow">Your private study record</div><h1>Notes & bookmarks.</h1><p>Your notes and bookmarks belong to the selected course. Export your full account to keep a copy.</p></div><button class="button button-secondary" data-action="export">Export JSON ↧</button></div><div class="detail-columns"><section class="card panel"><div class="panel-title"><h3>Saved notes</h3><span class="badge">${notes.length}</span></div>${notes.length?notes.map(([id,note])=>{if(id.startsWith('project-'))return `<div class="read-card"><b>${esc(id.replace('project-','Project '))}</b><p>${esc(note)}</p></div>`;const [wn,day]=id.split('-');return `<div class="read-card"><a href="#/learn/${wn}/${day}">Week ${wn} · ${esc(day)} note ↗</a><p>${esc(note)}</p></div>`}).join(''):'<div class="empty-state"><h3>No notes yet</h3><p>Write a reflection on any lesson or save project evidence.</p><a class="button button-secondary button-small" href="#/roadmap">Choose a study day</a></div>'}</section><section class="card panel"><div class="panel-title"><h3>Bookmarks</h3><span class="badge">${state.bookmarks.length}</span></div>${state.bookmarks.length?state.bookmarks.slice().reverse().map(b=>{if(b.type==='week')return `<div class="read-card"><a href="${weekLink(week(b.week))}">Week ${b.week} · ${esc(week(b.week)?.title||'Weekly plan')} ↗</a><button class="side-action" data-action="remove-bookmark" data-key="${esc(b.key)}">Remove</button></div>`;if(b.type==='day')return `<div class="read-card"><a href="#/learn/${b.week}/${String(b.day).toLowerCase()}">Week ${b.week} · ${esc(b.day)} study day ↗</a><button class="side-action" data-action="remove-bookmark" data-key="${esc(b.key)}">Remove</button></div>`;if(b.type==='chapter')return `<div class="read-card"><a href="${esc(b.url)}" target="_blank" rel="noopener noreferrer">${esc(b.id)} · ${esc(b.title)} ↗</a><small>Publisher-listed chapter · ${Number(b.startSeconds)} seconds</small><button class="side-action" data-action="remove-bookmark" data-key="${esc(b.key)}">Remove</button></div>`;if(b.type==='project')return `<div class="read-card"><a href="#/project/${b.id}">${esc(curriculum.projects.find(p=>p.id===b.id)?.title||b.id)} ↗</a><button class="side-action" data-action="remove-bookmark" data-key="${esc(b.key)}">Remove</button></div>`;const r=curriculum.resources.find(x=>x.id===b.id)||curriculum.videos.find(x=>x.id===b.id);return `<div class="read-card"><a href="#/resources/${b.id}">${esc(r?.id||b.id)} · ${esc(r?.title||'Saved source')} ↗</a><button class="side-action" data-action="remove-bookmark" data-key="${esc(b.key)}">Remove</button></div>`}).join(''):'<div class="empty-state"><h3>No saved sources</h3><p>Bookmark useful documentation or a specific video chapter.</p><a class="button button-secondary button-small" href="#/resources">Browse the library</a></div>'}</section></div><section class="card panel" style="margin-top:15px"><div class="panel-title"><h3>Revision queue</h3><span class="badge">${Object.values(state.assessments).filter(a=>a.status==='needs_revision').length} flagged</span></div>${Object.entries(state.assessments).filter(([,a])=>a.status==='needs_revision').map(([n])=>`<div class="task-check"><a href="#/assessments/${n}">Week ${n} · ${esc(week(n)?.title||'Assessment')} needs revision ↗</a></div>`).join('')||'<p class="small-muted">Assessments marked needs revision will appear here.</p>'}</section><section class="card panel" style="margin-top:15px"><div class="panel-title"><h3>Reported source issues</h3><span class="badge">${state.issues?.length||0}</span></div>${state.issues?.length?state.issues.map(issue=>`<div class="task-check">${esc(issue.resourceId)} · Reported ${new Date(issue.reportedAt).toLocaleDateString()}</div>`).join(''):'<p class="small-muted">No link issues reported.</p>'}</section>`;}
  function projectCard(p){return `<article class="card project-card"><div class="week-card-top"><span>${esc(p.id)}</span><span class="badge">Weeks ${esc(p.weeks)}</span></div><h3>${esc(p.title)}</h3><p>${esc(p.criteria)}</p><a class="button button-secondary button-small" href="#/project/${p.id}">Explore project →</a></article>`;}
  function setQuery(){const q=document.querySelector('#resource-search')?.value||'',type=document.querySelector('#resource-type')?.value||'all',status=document.querySelector('#resource-status')?.value||'all',module=document.querySelector('#resource-module')?.value||'all';const params=new URLSearchParams();if(q)params.set('q',q);if(type!=='all')params.set('type',type);if(status!=='all')params.set('status',status);if(module!=='all')params.set('module',module);history.replaceState(null,'',`#/${activeCourseId==='dsa'?'dsa/':''}resources${params.size?'?'+params.toString():''}`);renderResources();if(activeCourseId==='dsa')renderDsaExtras('resources',[]);const el=document.querySelector('#resource-search');if(el){el.focus();el.setSelectionRange(q.length,q.length)}}
  async function addBookmark(bookmark){if(state.bookmarks.some(b=>b.key===bookmark.key)){state.bookmarks=state.bookmarks.filter(b=>b.key!==bookmark.key);toast('Bookmark removed.')}else{bookmark.savedAt=new Date().toISOString();state.bookmarks.push(bookmark);toast('Saved to bookmarks.')}await save();render();toast('Bookmarks saved to your account.');}
  async function handleAction(action,el){if(action==='logout'){await Account.logout();return}if(action==='retry-save'){await save();toast('Changes saved to your account.');return}if(action==='retry-profile-progress'){loadProfileCourseProgress();return}const id=el.dataset.id,wn=Number(el.dataset.week);if(action==='save-profile'){const name=document.querySelector('#learner-name')?.value.trim();if(!name){toast('Add a display name first.');return}learner=await Account.updateName(name);render();toast('Profile saved to your account.');return}if(action==='save-course-start'){const value=document.querySelector('#course-start-date')?.value;if(!value||new Date(`${value}T00:00:00`).getDay()!==1){toast('Choose a Monday for the course start date.');return}state.courseStartDate=value;await save();render();toast('Course schedule updated.');return}if(action==='select-course'){const select=document.querySelector('#course-select');select.value=id;select.dispatchEvent(new Event('change'));return}if(action==='bookmark-resource')await addBookmark({key:`resource-${id}`,id,type:'resource'});if(action==='bookmark-chapter'){const video=curriculum.videos.find(v=>v.id===el.dataset.video),chapter=video?.chapters.find(c=>c.startSeconds===Number(el.dataset.start));if(video&&chapter)await addBookmark({key:`chapter-${video.id}-${chapter.startSeconds}`,id:video.id,title:chapter.title,startSeconds:chapter.startSeconds,url:chapter.url,type:'chapter'});}if(action==='report-issue'){state.issues||=[];state.issues.push({resourceId:id,reportedAt:new Date().toISOString()});await save();toast(`Issue saved for ${id} on this device.`);}if(action==='bookmark-week')await addBookmark({key:`week-${wn}`,week:wn,type:'week'});if(action==='bookmark-day')await addBookmark({key:`day-${wn}-${el.dataset.day}`,week:wn,day:el.dataset.day,type:'day'});if(action==='bookmark-project')await addBookmark({key:`project-${id}`,id,type:'project'});if(action==='remove-bookmark'){state.bookmarks=state.bookmarks.filter(b=>b.key!==el.dataset.key);await save();render();toast('Bookmark removed.')}if(action==='save-note'){const noteKey=el.dataset.note,rawLinks=document.querySelector(`[data-day-links="${noteKey}"]`)?.value||'',urls=rawLinks.split(/\s+/).filter(Boolean);if(urls.some(value=>{try{return new URL(value).protocol!=='https:'}catch{return true}})){toast('Use valid HTTPS links, one per line.');return}state.notes[noteKey]=document.querySelector(`[data-note="${noteKey}"]`)?.value||'';state.dayLinks||={};state.dayLinks[noteKey]=rawLinks.trim();await save();toast('Journal saved to your account.')}if(action==='save-project-note'){const rawUrl=document.querySelector(`[data-project-repo="${id}"]`)?.value.trim()||'';if(rawUrl){try{const parsed=new URL(rawUrl);if(parsed.protocol!=='https:'||!['github.com','www.github.com'].includes(parsed.hostname))throw new Error()}catch{toast('Enter a valid HTTPS GitHub repository URL.');return}}state.notes[`project-url-${id}`]=rawUrl;state.notes[`project-${id}`]=document.querySelector(`[data-project-note="${id}"]`)?.value||'';await save();toast('Project evidence saved.')}if(action==='print')window.print();if(action==='clear-search'){history.replaceState(null,'','#/resources');renderResources()}if(action==='export')await exportData();if(action==='submit-assessment'||action==='needs-revision'){const scores=[...document.querySelectorAll('[data-score]')].map(x=>Number(x.value));const checks=[...document.querySelectorAll('.assessment-grid input:checked')].map(x=>x.value);const critical=!!document.querySelector('[data-critical]')?.checked;const score=scores.reduce((a,b)=>a+b,0),evidence=document.querySelector('#assessment-evidence')?.value||'';if(action==='submit-assessment'&&(score<8||!critical||!evidence.trim())){toast('For a self-assessed pass, record ≥8/10, confirm critical checks, and add evidence.');return}if(activeCourseId==='dsa'&&state.assessments[wn]){state.dsa||={language:'cpp17',attempts:[],assessmentHistory:[]};state.dsa.assessmentHistory||=[];state.dsa.assessmentHistory.push({week:wn,...state.assessments[wn]})}state.assessments[wn]={status:action==='needs-revision'?'needs_revision':'self_assessed',scores,score,critical,evidence,updatedAt:new Date().toISOString()};await save();render();toast(action==='needs-revision'?'Added to your revision queue.':'Self-assessment recorded.');}}
  function downloadJSON(data,filename){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
  async function exportData(){try{const data=await Account.exportAll(drafts);downloadJSON(data,'coursecairn-account-export.json');toast('All course data exported.')}catch(error){if(Object.keys(drafts).length){downloadJSON({schemaVersion:1,profile:learner,exportedAt:new Date().toISOString(),unsavedDrafts:drafts},'coursecairn-unsaved-drafts.json');toast('Server unavailable. Exported your unsaved drafts; retry for your full account export.')}else toast(error.message)}}
  let searchTimer;main.addEventListener('input',e=>{if(e.target.matches('#resource-search')){clearTimeout(searchTimer);searchTimer=setTimeout(setQuery,180)}if(e.target.matches('#assessment-evidence')){}});main.addEventListener('change',async e=>{try{if(e.target.matches('#resource-type,#resource-status,#resource-module'))setQuery();if(e.target.matches('[data-task]')){const k=dayKey(e.target.dataset.week,e.target.dataset.day);state.progress[k]||={};state.progress[k][e.target.dataset.task]=e.target.checked;state.progress[k].updatedAt=new Date().toISOString();await save();const {page}=route();if(page==='learn'){const count=taskKeys(week(e.target.dataset.week)).filter(key=>state.progress[k][key]).length;const indicator=document.querySelector('.lesson-aside .panel:nth-child(2) .panel-title .small-muted');if(indicator)indicator.textContent=`${count}/${taskKeys(week(e.target.dataset.week)).length}`}toast('Progress saved to your account.')}if(e.target.matches('[data-score]')){const total=[...document.querySelectorAll('[data-score]')].reduce((s,x)=>s+Number(x.value),0);document.querySelector('#score-display').textContent=`${total}/10`}}catch(error){toast(error.message)}});main.addEventListener('click',async e=>{const a=e.target.closest('[data-action]');if(a){e.preventDefault();try{await handleAction(a.dataset.action,a)}catch(error){toast(error.message)}}});
  document.querySelector('#export-data').addEventListener('click',exportData);document.querySelector('#reset-data').addEventListener('click',async()=>{if(confirm('Reset this course’s progress, notes, bookmarks and assessments in your account? Export your data first if you need a copy.')){try{state={progress:{},notes:{},dayLinks:{},bookmarks:[],assessments:{},issues:[],courseStartDate:state.courseStartDate};await save();render();toast('Course progress reset.')}catch(error){toast(error.message)}}});document.querySelector('#menu-toggle').addEventListener('click',()=>document.querySelector('#sidebar').classList.toggle('open'));document.querySelector('#course-select').addEventListener('change',async e=>{const selected=catalog.courses.find(c=>c.id===e.target.value);if(!selected)return;try{const response=await fetch(`content/${selected.curriculum}`);if(!response.ok)throw new Error('Course content could not load.');curriculum=await response.json();activeCourseId=selected.id;localStorage.setItem(`coursecairn-active-course:${learner.id}`,activeCourseId);await initializeCourseState();history.replaceState(null,'',selected.id==='dsa'?'#/dsa/dashboard':'#/dashboard');render();toast(`${selected.title} opened.`)}catch(error){toast(error.message)}});document.addEventListener('click',e=>{if(innerWidth<760&&!e.target.closest('#sidebar')&&!e.target.closest('#menu-toggle'))document.querySelector('#sidebar').classList.remove('open')});window.addEventListener('hashchange',async()=>{try{if(location.hash.startsWith('#/dsa/')&&activeCourseId!=='dsa'){const response=await fetch('content/dsa-curriculum.json');if(!response.ok)throw new Error('DSA content could not load.');curriculum=await response.json();activeCourseId='dsa';document.querySelector('#course-select').value='dsa';localStorage.setItem(`coursecairn-active-course:${learner.id}`,'dsa');await initializeCourseState()}render();window.scrollTo(0,0)}catch(error){toast(error.message)}});
  async function openWorkspace(){learner=Account.user;document.body.classList.remove('auth-only');document.querySelector('#auth-root')?.remove();activeCourseId=location.hash.startsWith('#/dsa/')?'dsa':localStorage.getItem(`coursecairn-active-course:${learner.id}`)||catalog.activeCourseId;const select=document.querySelector('#course-select');select.innerHTML=catalog.courses.map(c=>`<option value="${esc(c.id)}">${esc(c.title)}</option>`).join('');if(!catalog.courses.some(c=>c.id===activeCourseId))activeCourseId=catalog.courses[0].id;select.value=activeCourseId;const selected=catalog.courses.find(c=>c.id===activeCourseId);const response=await fetch(`content/${selected.curriculum}`);if(!response.ok)throw new Error('Course content could not load.');curriculum=await response.json();await initializeCourseState();if(!location.hash)history.replaceState(null,'','#/courses');render();Account.status('All changes saved');}
  function renderAuth(mode='login',error=''){
    document.body.classList.add('auth-only');let root=document.querySelector('#auth-root');if(!root){root=document.createElement('div');root.id='auth-root';document.body.append(root)}
    const register=mode==='register',recover=mode==='recover';root.innerHTML=`<div class="auth-layout"><aside class="auth-story"><a class="brand" href="#"><span class="brand-mark">◒</span><span>CourseCairn<small>A little further, every day.</small></span></a><h1>Your learning.<br>Your own space.</h1><p>A personal path from your first line of code to the systems you want to build.</p><div class="auth-points"><span>01 · Choose your course</span><span>02 · Follow your daily plan</span><span>03 · Keep every step of progress</span></div></aside><section class="auth-card"><div class="eyebrow">WELCOME TO YOUR LEARNING STUDIO</div><h2>${register?'Create your account.':recover?'Recover your account.':'Pick up where you left off.'}</h2><p>${register?'Choose a unique username. Your courses and notes will belong to this account.':recover?'Use the recovery code saved when you created your account.':'Sign in to open your private courses, notes and progress.'}</p><form id="auth-form"><label for="auth-username">Unique username</label><input id="auth-username" name="username" autocomplete="username" minlength="3" maxlength="24" pattern="[A-Za-z0-9_]+" required placeholder="your_username">${register?'<label for="auth-name">Display name</label><input id="auth-name" name="displayName" maxlength="48" required autocomplete="nickname" placeholder="How should we call you?">':''}${recover?'<label for="auth-recovery">Recovery code</label><input id="auth-recovery" name="recoveryCode" required autocomplete="off">':''}<label for="auth-password">${recover?'New password':'Password'}</label><input id="auth-password" name="password" type="password" minlength="${register||recover?12:1}" maxlength="128" autocomplete="${register||recover?'new-password':'current-password'}" required>${register||recover?'<small>Use at least 12 characters. Keep your password private.</small><label for="auth-confirm">Confirm password</label><input id="auth-confirm" type="password" autocomplete="new-password" minlength="12" maxlength="128" required>':''}<p class="auth-error" id="auth-error" role="alert">${esc(error)}</p><button class="button button-primary" type="submit">${register?'Create account':recover?'Recover account':'Sign in'} ↗</button></form><div class="auth-switch">${register||recover?'<button data-auth-mode="login">Back to sign in</button>':'New here? <button data-auth-mode="register">Create an account</button><button data-auth-mode="recover">Forgot your password?</button>'}</div><button class="legacy-export" id="legacy-export">Export previous device notes</button></section></div>`;
    root.querySelectorAll('[data-auth-mode]').forEach(button=>button.addEventListener('click',()=>renderAuth(button.dataset.authMode)));
    root.querySelector('#legacy-export').addEventListener('click',()=>{const legacy={};for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key.startsWith(STORE+':')||key===LEARNER_STORE){try{legacy[key]=JSON.parse(localStorage.getItem(key))}catch{}}}downloadJSON({exportedAt:new Date().toISOString(),legacyDeviceData:legacy},'coursecairn-previous-device-data.json')});
    root.querySelector('form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,values=Object.fromEntries(new FormData(form)),button=form.querySelector('[type=submit]');if((register||recover)&&form.querySelector('#auth-confirm').value!==values.password){root.querySelector('#auth-error').textContent='Passwords do not match.';return}button.disabled=true;try{const result=await Account.authenticate(mode,values);if(result.recoveryCode){root.innerHTML=`<section class="recovery-card"><div class="eyebrow">KEEP THIS SOMEWHERE SAFE</div><h2>Your recovery code</h2><p>This code restores access if you forget your password. It is shown once. Recovery replaces it with a new code.</p><code id="recovery-code"></code><button class="button button-secondary" id="download-recovery">Download recovery code</button><button class="button button-primary" id="enter-workspace">I’ve saved it · open my courses ↗</button></section>`;root.querySelector('#recovery-code').textContent=result.recoveryCode;root.querySelector('#download-recovery').onclick=()=>downloadJSON({username:result.user.username,recoveryCode:result.recoveryCode},'coursecairn-recovery-code.json');root.querySelector('#enter-workspace').onclick=()=>openWorkspace().catch(e=>renderAuth('login',e.message));}else await openWorkspace()}catch(e){root.querySelector('#auth-error').textContent=e.message;button.disabled=false}});
  }
  (async()=>{try{const response=await fetch('content/catalog.json');if(!response.ok)throw new Error('Course catalog could not load.');catalog=await response.json();const user=await Account.boot();if(user)await openWorkspace();else renderAuth()}catch(error){renderAuth('login',error.message)}})();
})();
